// Ezekiel chapter notes.
import { makeBook } from "./make.js";

const sources = {
  block: "Daniel I. Block, The Book of Ezekiel, 2 vols., New International Commentary on the Old Testament (Eerdmans, 1997-98).",
  taylor: "John B. Taylor, Ezekiel, Tyndale Old Testament Commentaries (InterVarsity Press, 1969).",
  cooper: "Lamar Eugene Cooper Sr., Ezekiel, New American Commentary 17 (Broadman & Holman, 1994).",
  duguidE: "Iain M. Duguid, Ezekiel, NIV Application Commentary (Zondervan, 1999).",
  kitchen: "K. A. Kitchen, On the Reliability of the Old Testament (Eerdmans, 2003).",
  halot: "Koehler and Baumgartner, The Hebrew and Aramaic Lexicon of the Old Testament (Brill, 1994-2000).",
};

export default makeBook({ lang: "Hebrew", sources, use: ["block", "taylor"] }, {
  1: {
    intro: "In 593 BC Ezekiel, a priest among the exiles by the Chebar canal in Babylon, sees the heavens opened. A storm cloud with flashing fire comes from the north. In it are four living creatures, each with four faces (man, lion, ox, eagle) and wings, beside wheels \"full of eyes.\" Above them is a crystal expanse and a sapphire throne, and on the throne a figure like a man, glowing like fire, with a rainbow around Him. \"Such was the appearance of the likeness of the glory of the LORD.\" Ezekiel falls on his face.",
    v: [
      ["1:1", "The heavens were opened, and I saw visions of God", "Ezekiel was among the exiles by the Chebar canal in Babylonia, about 593 BC. There, far from the temple, the heavens opened. God meets His people even in exile."],
      ["1:10", "The face of a man... a lion... a bull... an eagle", "Church tradition later linked these to the four Gospels."],
      ["1:16", "A wheel within a wheel", "Able to go any direction: God is not limited to Jerusalem."],
      ["1:28", "Such was the appearance of the likeness of the glory of the LORD", "Ezekiel piles up careful words: \"the appearance of the likeness of the glory.\" He is describing something beyond words, and he falls on his face before it."],
    ],
    bg: [["The exiles by the Chebar", "Babylonian business records from Nippur mention the Kabaru canal and Jewish names, matching the setting of the exiles who were taken with King Jehoiachin in 597 BC.", "strong", ["kitchen", "block"]]],
    refs: [["REV.4", "Revelation 4:2-8", "The throne and four living creatures"], ["ISA.6", "Isaiah 6:1-5", "Isaiah's vision of the Lord"], ["DAN.7", "Daniel 7:9-10", "A fiery throne with wheels"]],
  },
  2: {
    intro: "\"Son of man, stand on your feet that I may speak with you.\" The Spirit enters Ezekiel and sets him on his feet. God sends him to rebellious, stubborn Israel: \"whether they listen or not... they will know that a prophet has been among them.\" \"Do not be afraid of them\" though they are like thorns and scorpions. A hand holds out a scroll written front and back with lamentations, mourning and woe.",
    v: [
      ["2:1", "Son of man", "God calls Ezekiel this over 90 times; it means \"human one.\" Jesus used it of Himself."],
      ["2:2", "The Spirit entered me and set me on my feet", "As God spoke, the Spirit entered Ezekiel and set him on his feet. God's Spirit gives His servant strength to stand and listen."],
      ["2:5", "Whether they listen or not", "Faithfulness, not results, is the calling."],
    ],
    w: [["בֶּן־אָדָם", "ben-adam", "H1121", "son of man, human being", "God calls Ezekiel \"son of man\" over ninety times. It stresses that he is only human before a glorious God. Jesus' favorite name for Himself, \"the Son of Man,\" draws more on Daniel 7:13, where it names a heavenly figure.", ["halot", "block"]]],
    refs: [["DAN.7", "Daniel 7:13", "One like a son of man"], ["MRK.2", "Mark 2:10", "The Son of Man has authority"], ["JER.1", "Jeremiah 1:8", "Do not be afraid"]],
  },
  3: {
    intro: "God tells Ezekiel to eat the scroll, and it is as sweet as honey. He is sent to his own people, who will not listen. \"I have appointed you a watchman to the house of Israel.\" If he fails to warn the wicked, their blood will be on his hands; if he warns them, he has saved himself. God makes him unable to speak except when God gives him a message.",
    v: [
      ["3:3", "It was sweet as honey in my mouth", "God gave Ezekiel a scroll to eat, and it tasted sweet as honey. God's word must be taken inside before it is spoken (compare Jeremiah 15:16; Revelation 10:9-10)."],
      ["3:17", "I have appointed you a watchman", "A watchman stood on the city wall to warn of approaching danger. God makes Ezekiel a watchman for His people."],
      ["3:18-19", "If you warn the wicked", "If the watchman warns and the wicked will not turn, the watchman has done his part. If he stays silent, he shares the blame. Speaking God's warning is a serious responsibility."],
    ],
    bg: [["Sweet as honey", "Ezekiel ate the scroll God gave him, and \"it was sweet as honey in my mouth\" (3:3), though its message was lament and woe (2:10). John has a similar experience in Revelation 10:9-10. God's word must be taken in before it can be spoken.", "good", ["block", "taylor"]]],
    refs: [["JER.15", "Jeremiah 15:16", "Your words were found and I ate them"], ["REV.10", "Revelation 10:9-10", "Sweet as honey"], ["EZK.33", "Ezekiel 33:1-9", "The watchman again"]],
  },
  4: {
    intro: "Ezekiel acts out Jerusalem's siege. He draws the city on a clay brick, builds tiny siege works around it, and lies on his side for many days bearing the people's guilt. He eats measured rations of mixed-grain bread and water, a picture of famine in the besieged city.",
    v: [
      ["4:1", "Take a brick... and inscribe a city on it", "Ezekiel drew Jerusalem on a clay brick and built a model siege around it, like a child's war game with a deadly message."],
      ["4:4-6", "Lie on your left side... bear their iniquity", "Ezekiel lay on his left side 390 days for Israel and on his right side 40 days for Judah, one day for each year of their sin."],
      ["4:9", "Wheat, barley, beans, lentils, millet and spelt", "Scraping together whatever grain is left."],
    ],
    bg: [["Sermons without words", "Ezekiel acted out Jerusalem's siege: a model city on a clay brick, lying on his left side 390 days and on his right 40 days, and eating rationed bread (4:1-10). When he protested baking over human dung, God allowed cow dung instead (4:14-15). His actions spoke when words were ignored.", "good", ["block", "duguidE"]]],
    refs: [["JER.19", "Jeremiah 19", "Another acted-out message"], ["2KI.25", "2 Kings 25:1-3", "The siege and famine"]],
  },
  5: {
    intro: "Ezekiel shaves his head and beard with a sword and divides the hair into thirds: one burned in the city, one struck with the sword, one scattered to the wind. A few hairs are tucked into his robe. So Jerusalem, set at the center of the nations, will be judged for rebelling more than the nations around her, though a remnant will survive.",
    v: [
      ["5:3", "Bind them in the edges of your robes", "After shaving his head, Ezekiel was to tuck a few hairs into the edge of his robe. A small remnant of God's people would be kept safe."],
      ["5:5", "This is Jerusalem; I have set her at the center of the nations", "God set Jerusalem at the center of the nations to show them His ways. Greater privilege brought greater responsibility, and greater judgment when she rebelled (5:6)."],
      ["5:1", "Take a sharp sword; take and use it as a barber's razor", "The sword that shaves Ezekiel stands for the Babylonian army that will strip the land (compare Isaiah 7:20)."],
      ["5:10", "Fathers will eat their sons among you", "The horror warned of in Leviticus 26:29 and Deuteronomy 28:53, and mourned after the siege in Lamentations 4:10."],
      ["5:13", "I, the LORD, have spoken in My zeal", "God's judgment is not cold. It comes from jealous, covenant love for His people."],
    ],
    bg: [["A priest shaves his head", "Ezekiel was a priest (1:3), and priests were told not to shave their heads (Leviticus 21:5). Shaving was also a sign of mourning and disgrace (Isaiah 15:2). The act itself announced that something terrible was coming to God's holy city.", "good", ["block", "duguidE"]]],
    refs: [["ISA.6", "Isaiah 6:13", "A holy seed remains"], ["LUK.12", "Luke 12:48", "To whom much is given"]],
  },
  6: {
    intro: "Ezekiel prophesies against the mountains of Israel, where the idol shrines stand. The altars will be ruined and the idols broken. Yet a remnant will remember God among the nations and loathe themselves for their evil. Again and again: \"Then you will know that I am the LORD.\"",
    v: [
      ["6:9", "How I have been hurt by their adulterous hearts", "God says He has been hurt, even broken, by their unfaithful hearts and wandering eyes. Their idolatry grieved Him like a betrayal in a marriage."],
      ["6:10", "Then they will know that I am the LORD", "This phrase appears over 60 times in Ezekiel."],
      ["6:3", "You mountains of Israel", "Ezekiel speaks to the land itself, because its hilltops were covered with shrines to other gods."],
      ["6:13", "Under every green tree", "A common phrase for the places where idols were worshiped (Deuteronomy 12:2; Jeremiah 2:20)."],
    ],
    w: [["גִּלּוּלִים", "gillulim", "H1544", "idols", "Ezekiel's favorite word for idols, used about 39 times in his book. Many scholars think it was coined to sound like the word for dung, a scornful pun: \"dung-gods.\"", ["halot", "block"]]],
    refs: [["LEV.26", "Leviticus 26:30", "I will destroy your high places"], ["HOS.11", "Hosea 11:8", "How can I give you up?"]],
  },
  7: {
    intro: "\"An end! The end is coming on the four corners of the land.\" The day of doom has come. People will throw their silver into the streets, because it cannot save them. They will seek a vision from the prophet, but the law will perish from the priest.",
    v: [
      ["7:2", "An end! The end is coming", "\"An end! The end is coming on the four corners of the land.\" Ezekiel announces that final judgment on Judah has arrived."],
      ["7:12", "Let not the buyer rejoice nor the seller mourn", "Business as usual means nothing when judgment comes."],
      ["7:19", "Their silver and gold will not be able to deliver them", "People will throw their silver into the streets, because silver and gold cannot save them in the day of the LORD's wrath (Zephaniah 1:18)."],
      ["7:26", "They will seek a vision from a prophet", "When it is too late, people look for a word from God."],
    ],
    bg: [["Short, hammering words", "Chapter 7 is a poem of alarm, with short cries repeated again and again: \"An end! The end has come!\" Jerusalem fell a few years later, in 586 BC.", "good", ["block", "taylor"]]],
    refs: [["ZEP.1", "Zephaniah 1:18", "Neither silver nor gold will deliver them"], ["AMO.8", "Amos 8:2", "The end has come"]],
  },
  8: {
    intro: "In a vision the Spirit lifts Ezekiel by his hair to the Jerusalem temple. He sees an idol at the gate, seventy elders burning incense to creeping things in a secret room, women weeping for the god Tammuz, and twenty-five men with their backs to the temple bowing to the sun. \"Have you seen this, son of man?\"",
    v: [
      ["8:12", "The LORD does not see us", "In the dark, Israel's elders worshiped carved images, saying, \"The LORD does not see us.\" Secret sin assumes God doesn't notice."],
      ["8:14", "Women weeping for Tammuz", "Tammuz was a Mesopotamian god whose yearly \"death\" was mourned with weeping. God's own people had brought his worship into the temple gate."],
      ["8:16", "Their backs to the temple of the LORD and their faces toward the east", "About twenty-five men stood between the porch and the altar with their backs to the temple, bowing to the sun in the east. They literally turned their backs on God."],
    ],
    bg: [["Weeping for Tammuz", "In a vision Ezekiel saw idolatry inside the temple: elders burning incense in a dark room, women weeping for Tammuz (8:14), and men with their backs to the temple bowing to the sun (8:16). Tammuz was a Mesopotamian god whose death was mourned each summer as plants withered.", "strong", ["block", "taylor"]]],
    refs: [["PSA.94", "Psalm 94:7-9", "He who planted the ear, does He not hear?"], ["2KI.21", "2 Kings 21:3-5", "Manasseh's idolatry"]],
  },
  9: {
    intro: "God calls executioners to the city. First, a man clothed in linen with a writing case is told to put a mark on the foreheads of all who sigh and groan over the abominations. The executioners spare those with the mark. Ezekiel cries, \"Alas, Lord GOD! Are You destroying the whole remnant?\"",
    v: [
      ["9:4", "Put a mark on the foreheads of the men who sigh and groan", "A man with a writing case marks the foreheads of those who grieve over the city's sins. The mark is the Hebrew letter taw, which in the old script was shaped like an X. God knows and protects His own (Revelation 7:3)."],
      ["9:6", "Start from My sanctuary", "\"Start from My sanctuary.\" Judgment begins with the leaders at God's house (1 Peter 4:17)."],
      ["9:8", "Alas, Lord GOD!", "Left alone, Ezekiel falls on his face and cries, \"Alas, Lord GOD!\" The prophet pleads for his people."],
    ],
    w: [["תָּו", "tav", "H8420", "mark; the last letter of the Hebrew alphabet", "A man in linen put a mark on the foreheads of those who grieved over the city's sins, and they were spared (9:4). The mark is the letter tav, which in the old Hebrew script looked like an X or a cross. Revelation 7:3 pictures God's servants sealed on their foreheads.", ["halot", "block"]]],
    refs: [["REV.7", "Revelation 7:3", "Sealed on their foreheads"], ["1PE.4", "1 Peter 4:17", "Judgment begins with the household of God"], ["EXO.12", "Exodus 12:13", "The blood as a sign"]],
  },
  10: {
    intro: "The vision continues. The man in linen takes burning coals from among the cherubim and scatters them over the city. Then the glory of the LORD rises from the temple, pauses at the threshold, and moves to the east gate with the cherubim and wheels. God's presence is leaving His house.",
    v: [
      ["10:4", "The glory of the LORD went up from the cherub to the threshold", "The glory of the LORD rises from above the cherubim to the threshold of the temple. God's presence begins to leave."],
      ["10:18", "The glory of the LORD departed from the threshold", "The glory leaves the threshold and moves to the east gate (10:19). It is the saddest moment in Ezekiel: God is leaving His own house."],
      ["10:20", "I knew that they were cherubim", "Ezekiel realizes these are the same living creatures he saw by the river Chebar (chapter 1). They are cherubim, the guardians of God's throne."],
    ],
    bg: [["The glory departs", "The glory of God left the temple in stages, as if reluctant: from the cherubim to the threshold (10:4), to the east gate (10:19), and then to the mountain east of the city (11:23). In chapter 43 Ezekiel sees it return by the same way.", "strong", ["block", "duguidE"]]],
    refs: [["1SA.4", "1 Samuel 4:21-22", "Ichabod: the glory has departed"], ["EZK.43", "Ezekiel 43:1-5", "The glory returns"]],
  },
  11: {
    intro: "Leaders in Jerusalem claim they are the safe \"meat in the pot.\" God says they will be judged. Ezekiel asks again whether all will be destroyed. God answers that He Himself has been \"a sanctuary for them a little while\" among the exiles. \"I will give them one heart, and put a new spirit within them. And I will take the heart of stone out of their flesh and give them a heart of flesh.\" The glory leaves the city and stands over the Mount of Olives.",
    v: [
      ["11:16", "I was a sanctuary for them a little while", "Those left in Jerusalem said the exiles were far from God. But God says He had been a sanctuary for them in the lands where they went. God was with the exiles."],
      ["11:19", "A heart of flesh", "God will take away the heart of stone and give a heart of flesh, soft and alive to Him. He gives a new heart (36:26)."],
      ["11:23", "The glory of the LORD went up... and stood over the mountain east of the city", "The glory stops over the mountain east of the city, the Mount of Olives. Later Ezekiel sees it return from the east (43:2-4)."],
    ],
    bg: [["A heart of flesh", "\"I will give them one heart, and put a new spirit within them. And I will take the heart of stone out of their flesh and give them a heart of flesh\" (11:19). The promise is repeated and expanded in 36:26-27. God was already planning renewal while announcing judgment.", "good", ["block", "taylor"]]],
    refs: [["EZK.36", "Ezekiel 36:26", "A new heart"], ["JER.31", "Jeremiah 31:33", "Written on their heart"], ["ACT.1", "Acts 1:9-12", "Jesus ascends from the Mount of Olives"]],
  },
  12: {
    intro: "Ezekiel packs an exile's bag, digs through the wall at evening, and leaves with his face covered. It is a sign: the prince in Jerusalem will flee by night and be captured, yet will not see Babylon though he dies there. People say, \"The days are long and every vision fails,\" but God says the time is near.",
    v: [
      ["12:6", "I have set you as a sign", "Ezekiel packed a bag and dug through a wall at night as if escaping. King Zedekiah later fled Jerusalem through a wall by night (2 Kings 25:4). Ezekiel's actions preached."],
      ["12:13", "He will not see it, though he will die there", "Zedekiah was blinded and taken to Babylon."],
      ["12:28", "None of My words will be delayed any longer", "People said the visions were for the distant future. God says, \"None of My words will be delayed any longer.\" What He says will come true."],
    ],
    bg: [["He will not see it", "Ezekiel dug through a wall at night and carried out his baggage, acting out the king's escape (12:3-12). God said the prince would be taken to Babylon, \"yet he will not see it, though he will die there\" (12:13). King Zedekiah was captured, blinded and taken to Babylon (2 Kings 25:4-7).", "strong", ["block", "taylor"]]],
    refs: [["JER.39", "Jeremiah 39:4-7", "Zedekiah captured and blinded"], ["2PE.3", "2 Peter 3:4, 9", "Where is the promise?"]],
  },
  13: {
    intro: "Woe to the foolish prophets who follow their own spirit and have seen nothing. They say \"Peace!\" when there is no peace, like men covering a flimsy wall with whitewash. A storm of God's anger will knock it down. Women who sell magic charms are also condemned.",
    v: [
      ["13:3", "Who follow their own spirit and have seen nothing", "Woe to the foolish prophets who follow their own spirit and have seen nothing. Prophecy without God is only human opinion."],
      ["13:10", "Peace! when there is no peace", "The false prophets say \"Peace!\" when there is no peace. They are like men who whitewash a shaky wall: it looks fine until the storm comes."],
      ["13:11", "They plaster it over with whitewash", "Covering problems instead of fixing them."],
    ],
    bg: [["Whitewashed walls", "False prophets were like men who smear whitewash on a flimsy wall: it looks solid until the storm hits (13:10-12). They said \"Peace\" when there was none. Jesus called hypocrites \"whitewashed tombs\" (Matthew 23:27).", "good", ["block", "cooper"]]],
    refs: [["JER.6", "Jeremiah 6:14", "Peace, peace"], ["MAT.23", "Matthew 23:27", "Whitewashed tombs"]],
  },
  14: {
    intro: "Elders come to Ezekiel, but they have set up idols in their hearts. God says that even if Noah, Daniel and Job were in a land under judgment, they would save only themselves by their righteousness. Yet a remnant will survive, and others will be comforted when they see why God acted.",
    v: [
      ["14:3", "These men have set up their idols in their hearts", "The elders came to ask God's will, but they had already set up idols in their hearts. Idolatry can be inward, a rival love no one else can see."],
      ["14:7", "Who separates himself from Me and sets up his idols in his heart", "Coming to a prophet does not cover a divided heart."],
      ["14:14", "Noah, Daniel and Job", "Noah, Daniel and Job were famous for righteousness, yet even they could save only themselves. Some think this Daniel is Ezekiel's fellow exile; others think he is an ancient righteous man named Danel, known from old Canaanite stories."],
      ["14:22-23", "You will be comforted", "When survivors arrive, the exiles will see that God's judgment was just."],
    ],
    bg: [["Which Daniel?", "Ezekiel names Noah, Daniel and Job as famous righteous men. Many think this Daniel is Ezekiel's younger contemporary in Babylon, already known for wisdom and faithfulness (Daniel 1-2; Ezekiel 28:3). Others note that the Hebrew spelling matches Dan'el, an ancient righteous king in texts from Ugarit, who would fit with the ancient figures Noah and Job.", "debated", ["block", "taylor"]]],
    refs: [["DAN.1", "Daniel 1", "Daniel's faithfulness"], ["JOB.1", "Job 1:1", "Blameless and upright"], ["1JN.5", "1 John 5:21", "Guard yourselves from idols"]],
  },
  15: {
    intro: "A vine is valuable only for its fruit; its wood is useless, not even good enough to make a peg. If it is burned, it is good for nothing. So Jerusalem, which bore no fruit, will be given to the fire.",
    v: [
      ["15:2", "How is the wood of the vine better than any wood?", "Vine wood is too weak to make even a peg for hanging a pot (15:3). A vine is good for one thing: bearing fruit."],
      ["15:3", "Can a peg be taken from it to hang any vessel on?", "Vine wood is too twisted and weak even for a peg."],
      ["15:6", "As the wood of the vine... so I have given up the inhabitants of Jerusalem", "Like a fruitless vine fit only for the fire, Jerusalem has failed to bear fruit for God. Jesus uses the same picture in John 15:6."],
      ["15:7", "Though they have come out of the fire, the fire will consume them", "Jerusalem had already been burned once (597 BC) but had not repented."],
    ],
    bg: [["Israel as God's vine", "The Bible often calls Israel God's vine (Psalm 80:8-16; Isaiah 5). A vine's only value is fruit. Jesus took up the same picture: \"I am the true vine... apart from Me you can do nothing\" (John 15:1-5).", "good", ["block", "duguidE"]]],
    refs: [["PSA.80", "Psalm 80:8-16", "You brought a vine out of Egypt"], ["JHN.15", "John 15:1-6", "Abide in the vine"], ["ISA.5", "Isaiah 5:1-7", "The fruitless vineyard"]],
  },
  16: {
    intro: "An allegory of Jerusalem as an abandoned baby girl, left in a field on the day she was born. God passed by, said \"Live!\", raised her, married her, and clothed her in splendor. But she trusted in her beauty and became unfaithful with idols and foreign nations. Yet God will remember His covenant: \"I will establish an everlasting covenant with you... when I have forgiven you for all that you have done.\"",
    v: [
      ["16:6", "I said to you while you were in your blood, Live!", "God pictures Israel as an abandoned baby left in the open field, and He says, \"Live!\" His love began with sheer grace to the helpless."],
      ["16:15", "You trusted in your beauty", "God made her beautiful, but she trusted in her beauty and gave herself to others. His gifts became her idols."],
      ["16:60", "I will remember My covenant with you", "After all her unfaithfulness, God says, \"I will remember My covenant with you... and I will establish an everlasting covenant.\" Mercy follows betrayal."],
      ["16:63", "When I have forgiven you", "When God forgives, Israel will be ashamed and silent. Being forgiven so freely is humbling."],
    ],
    bg: [["The sin of Sodom", "Ezekiel tells Jerusalem's story as an abandoned baby girl God rescued and raised, who later betrayed Him (16:4-15). The language is strong, meant to shock. He even calls Sodom her sister, whose guilt included pride, plenty and ease, while she \"did not help the poor and needy\" (16:49).", "good", ["block", "duguidE"]]],
    refs: [["HOS.2", "Hosea 2", "The unfaithful wife restored"], ["EPH.2", "Ephesians 2:1-5", "Dead in sin, made alive"]],
  },
  17: {
    intro: "A riddle: a great eagle (Babylon) plants a vine (Zedekiah), but the vine stretches toward another eagle (Egypt). Because Zedekiah broke his oath, he will be judged. Then God promises to take a tender sprig from the top of the cedar and plant it on a high mountain, where it will become a stately cedar and birds of every kind will nest in it.",
    v: [
      ["17:15", "He rebelled against him by sending his envoys to Egypt", "Zedekiah had sworn an oath of loyalty to Nebuchadnezzar, then broke it by sending to Egypt for help. God treats a broken oath as a serious matter (17:19)."],
      ["17:22", "I will take a tender twig and plant it on a high mountain", "God will take a tender twig from the top of the cedar and plant it on a high mountain. It is a picture of a future King from David's line (Isaiah 11:1)."],
      ["17:23", "Birds of every kind will nest under it", "Like Jesus' parable of the mustard seed."],
    ],
    bg: [["Two eagles and a twig", "The riddle of the eagles describes history: Nebuchadnezzar took King Jehoiachin to Babylon, and Zedekiah broke his oath by turning to Egypt (17:12-15). Then God Himself will plant a tender twig on a high mountain, and it will become a great cedar where birds nest (17:22-24), a picture of a coming King.", "good", ["block", "taylor"]]],
    refs: [["MAT.13", "Matthew 13:31-32", "The birds nest in its branches"], ["ISA.11", "Isaiah 11:1", "A shoot from Jesse"]],
  },
  18: {
    intro: "The people quote a proverb: \"The fathers eat sour grapes, but the children's teeth are set on edge,\" blaming their parents for their troubles. God says, \"The soul who sins will die.\" Each person is responsible. A righteous son of a wicked father will live; a wicked man who turns from his sins will live. \"I have no pleasure in the death of anyone who dies... Therefore, repent and live.\"",
    v: [
      ["18:2", "The fathers eat sour grapes", "The proverb said the fathers ate sour grapes and the children's teeth were set on edge. The people blamed their troubles on past generations (Jeremiah 31:29)."],
      ["18:4", "All souls are Mine", "\"All souls are Mine.\" Every person belongs to God and answers to Him for his own life."],
      ["18:23", "Do I have any pleasure in the death of the wicked?", "\"Do I have any pleasure in the death of the wicked... rather than that he should turn from his ways and live?\" God wants people to turn and live (2 Peter 3:9)."],
      ["18:31", "Make yourselves a new heart and a new spirit", "\"Cast away from you all your transgressions... and make yourselves a new heart and a new spirit!\" Turn now; there is still time."],
      ["18:32", "Therefore, repent and live", "\"I have no pleasure in the death of anyone... Therefore, repent and live.\" The chapter ends with God's open invitation."],
    ],
    bg: [["Sour grapes", "The exiles quoted a proverb: \"The fathers eat the sour grapes, but the children's teeth are set on edge\" (18:2). They blamed their ancestors. God answered that each person is responsible for their own choices, and that He has no pleasure in anyone's death: \"Repent and live\" (18:32).", "strong", ["block", "duguidE"]]],
    refs: [["JER.31", "Jeremiah 31:29-30", "The same proverb"], ["2PE.3", "2 Peter 3:9", "Not wishing for any to perish"], ["DEU.24", "Deuteronomy 24:16", "Each for his own sin"]],
  },
  19: {
    intro: "A lament for Israel's princes. Their mother was a lioness whose cubs became young lions; one was caught and taken to Egypt (Jehoahaz), another to Babylon (Jehoiachin). Then their mother was a vine, once fruitful, now plucked up and planted in the wilderness.",
    v: [
      ["19:4", "They brought him with hooks to the land of Egypt", "The young lion taken to Egypt with hooks is King Jehoahaz, carried off by Pharaoh Neco (2 Kings 23:33-34)."],
      ["19:9", "They brought him to the king of Babylon", "The second young lion, put in a cage and taken to Babylon, is most likely King Jehoiachin (2 Kings 24:15)."],
      ["19:14", "This is a lamentation", "\"This is a lamentation, and has become a lamentation.\" Ezekiel grieves for David's fallen royal house."],
    ],
    bg: [["A lament for lions", "Ezekiel sings a funeral song (in Hebrew a qinah, with a limping rhythm) over Judah's kings pictured as young lions. One was taken to Egypt, likely Jehoahaz (2 Kings 23:33); the other to Babylon, likely Jehoiachin (2 Kings 24:15).", "good", ["block", "taylor"]]],
    refs: [["2KI.23", "2 Kings 23:31-34", "Jehoahaz taken to Egypt"], ["2KI.24", "2 Kings 24:12-15", "Jehoiachin taken to Babylon"]],
  },
  20: {
    intro: "Elders come again. God retells Israel's history of rebellion in Egypt, in the wilderness, and in the land, and how He acted \"for the sake of My name\" each time. He will not be consulted by them now. But He will bring them out, purge the rebels, and accept them as a soothing aroma. \"Then you will know that I am the LORD, when I have dealt with you for My name's sake.\"",
    v: [
      ["20:9", "I acted for the sake of My name", "Again and again Israel rebelled, yet God held back, acting \"for the sake of My name.\" His mercy protects His honor among the nations."],
      ["20:12", "I gave them My sabbaths to be a sign", "God gave the Sabbath as a sign between Him and His people, so they would know He makes them holy (Exodus 31:13)."],
      ["20:44", "Not according to your evil ways", "God will deal with them for His name's sake, \"not according to your evil ways.\" It is grace they did not deserve."],
    ],
    bg: [["For My name's sake", "In 591 BC elders came to ask God's will (20:1). God replied with Israel's whole history of rebellion, from Egypt onward. Again and again He says He held back judgment \"for the sake of My name\" (20:9, 14, 22). His faithfulness rests on who He is.", "good", ["block", "duguidE"]]],
    refs: [["PSA.106", "Psalm 106", "Israel's rebellion and God's mercy"], ["NEH.9", "Nehemiah 9", "A similar retelling"]],
  },
  21: {
    intro: "\"A sword, a sword sharpened and polished!\" God draws His sword against Jerusalem. The king of Babylon stands at a fork in the road, casting lots, consulting idols and looking at a liver, and the lot points to Jerusalem. The crown will be removed \"until He comes whose right it is, and I will give it to Him.\"",
    v: [
      ["21:9", "A sword, a sword sharpened", "\"A sword, a sword sharpened and also polished!\" The sword of Babylon is ready, and judgment is near."],
      ["21:21", "He looks at the liver", "Babylonian fortune-telling, yet God directs the outcome."],
      ["21:27", "Until He comes whose right it is", "The crown will be overturned \"until He comes whose right it is.\" It echoes Genesis 49:10, a promise of the rightful King to come."],
    ],
    bg: [["A king at a crossroads", "Nebuchadnezzar is pictured at a fork in the road, choosing between Jerusalem and Ammon. He shakes arrows, consults household idols and looks at a liver (21:21). Babylonian texts confirm these ways of seeking omens. God used even pagan divination to bring His judgment.", "strong", ["block", "kitchen"]]],
    refs: [["GEN.49", "Genesis 49:10", "Until Shiloh comes"], ["PRO.16", "Proverbs 16:33", "The decision is from the LORD"]],
  },
  22: {
    intro: "A list of Jerusalem's sins: bloodshed, idols, contempt for parents, oppression of strangers, orphans and widows, bribery, broken sabbaths. Israel has become dross in God's furnace. Prophets, priests, princes and people are all corrupt. \"I searched for a man among them who would build up the wall and stand in the gap before Me for the land... but I found no one.\"",
    v: [
      ["22:7", "They have treated father and mother lightly", "In Jerusalem, father and mother are treated with contempt, and strangers, orphans and widows are wronged. The basic respect God commanded (Exodus 20:12) has broken down."],
      ["22:18", "Israel has become dross to Me", "When silver is refined, the dross is the worthless waste left behind. Israel has become dross to God."],
      ["22:30", "Stand in the gap before Me", "God searched for a man who would build up the wall and stand in the gap before Him for the land, \"but I found no one.\" God looked for someone to pray and stand for the people."],
    ],
    bg: [["Standing in the gap", "\"I searched for a man among them who would build up the wall and stand in the gap before Me for the land... but I found no one\" (22:30). Prophets, priests, princes and people had all failed (22:25-29). Moses once stood in the breach for Israel (Psalm 106:23).", "strong", ["block", "taylor"]]],
    refs: [["ISA.59", "Isaiah 59:16", "No one to intercede"], ["PSA.106", "Psalm 106:23", "Moses stood in the breach"], ["HEB.7", "Hebrews 7:25", "Christ always intercedes"]],
  },
  23: {
    intro: "An allegory of two sisters, Oholah (Samaria) and Oholibah (Jerusalem), who were unfaithful to God by chasing alliances with Egypt, Assyria and Babylon and their idols. Samaria was judged first; Jerusalem saw it and did worse. Both will drink the cup of judgment.",
    v: [
      ["23:4", "Oholah... and Oholibah", "Names meaning \"her tent\" and \"My tent is in her.\""],
      ["23:11", "Her sister Oholibah saw this, yet she was more corrupt", "Oholibah (Jerusalem) watched her sister Oholah (Samaria) fall, yet she became even more corrupt. She did not learn from her sister's ruin."],
      ["23:49", "Then you will know that I am the Lord GOD", "The chapter ends, \"Then you will know that I am the Lord GOD.\" The goal of judgment is that people come to know God."],
    ],
    bg: [["Two sisters", "Samaria and Jerusalem are pictured as two sisters, Oholah and Oholibah (23:4). The names likely mean \"her tent\" and \"my tent is in her,\" perhaps contrasting Samaria's own shrines with God's temple in Jerusalem. Both chased foreign alliances and gods.", "good", ["block", "cooper"]]],
    refs: [["JER.3", "Jeremiah 3:6-10", "Faithless Israel and treacherous Judah"], ["2KI.17", "2 Kings 17", "Samaria falls"]],
  },
  24: {
    intro: "On the very day Babylon begins the siege of Jerusalem (January 588 BC), God gives Ezekiel a parable of a rusty cooking pot. Then God tells him that his wife, \"the desire of your eyes,\" will die suddenly, and he must not mourn publicly. She dies that evening. It is a sign: Jerusalem, the desire of their eyes, will fall, and they will be too stunned to mourn.",
    v: [
      ["24:2", "Write the name of the day, this very day", "Ezekiel was told to write down the exact date, because that very day the king of Babylon laid siege to Jerusalem, in January 588 BC (2 Kings 25:1). Jews still keep a fast on that day, the tenth of Tevet."],
      ["24:16", "The desire of your eyes", "God tells Ezekiel that He is about to take \"the desire of your eyes\" with one stroke. It was Ezekiel's beloved wife."],
      ["24:18", "In the evening my wife died", "Ezekiel spoke to the people in the morning, and in the evening his wife died. His obedience cost him heartbreak."],
      ["24:24", "Ezekiel will be a sign to you", "Ezekiel was told not to mourn openly. His silent grief would show the people how they would react when the temple, the delight of their eyes, was destroyed."],
    ],
    bg: [["The day the siege began", "God told Ezekiel to write down the date: Jerusalem's siege began that very day (24:1-2), January 588 BC (2 Kings 25:1). The same day Ezekiel's wife, \"the desire of your eyes,\" died, and he was told not to mourn openly (24:16-18). His silent grief was a sign of the grief coming to all.", "strong", ["block", "kitchen"]]],
    refs: [["2KI.25", "2 Kings 25:1", "The siege begins"], ["HOS.1", "Hosea 1:2", "A prophet's family as a sign"]],
  },
  25: {
    intro: "Oracles against Israel's neighbors begin (25-32). Ammon clapped its hands when the temple was profaned; Moab said Judah was like all the nations; Edom and Philistia took revenge. Each will be judged, \"and they will know that I am the LORD.\"",
    v: [
      ["25:3", "Because you said, Aha!", "Ammon said \"Aha!\" when the temple was profaned and Judah went into exile. God judges those who gloat over others' ruin (Proverbs 24:17-18)."],
      ["25:6", "Because you have clapped your hands and stamped your feet", "Ammon clapped its hands, stamped its feet and rejoiced with contempt at Judah's fall. Their celebration of someone else's grief was itself a sin."],
      ["25:8", "Judah is like all the nations", "Moab mocked the idea that Israel's God was special."],
      ["25:12", "Edom has acted against the house of Judah by taking vengeance", "Edom, descended from Jacob's brother Esau, took revenge on Judah in its weakest hour (Obadiah 10-14). God judges revenge."],
      ["25:15", "The Philistines have acted in revenge", "The Philistines acted with \"everlasting enmity\" and used Judah's fall to take revenge. Old hatred took its chance."],
    ],
    bg: [["Four neighbors", "Ammon and Moab lay east of the Jordan, Edom to the southeast, and Philistia on the coast to the west. All four had long histories of conflict with Israel, and all four rejoiced when Jerusalem fell in 586 BC.", "good", ["block", "taylor"]]],
    refs: [["OBA.1", "Obadiah 12", "Do not gloat"], ["PRO.24", "Proverbs 24:17", "Do not rejoice when your enemy falls"]],
  },
  26: {
    intro: "Tyre, the rich island trading city, rejoiced at Jerusalem's fall, hoping to profit. God will bring many nations against her like waves. Nebuchadnezzar will besiege her; her stones and timber will be thrown into the sea, and she will become a bare rock for spreading fishing nets.",
    v: [
      ["26:2", "Aha, the gateway of the peoples is broken", "Tyre, a rich trading city, cheered Jerusalem's fall as a competitor knocked out of business: \"I shall be filled, now that she is laid waste.\" Greed profits from another's loss."],
      ["26:3", "As the sea brings up its waves", "God will bring many nations against Tyre, like waves the sea throws up one after another. Tyre would face attacker after attacker over the centuries."],
      ["26:14", "A bare rock... a place for the spreading of nets", "Tyre will become a bare rock where fishermen spread their nets to dry. Nebuchadnezzar besieged it for thirteen years, and in 332 BC Alexander the Great scraped the old city's rubble into the sea to build a causeway to the island fortress."],
    ],
    why: "Ezekiel 26 says Nebuchadnezzar would besiege Tyre and that Tyre would be scraped bare and never rebuilt. Scholars discuss how this was fulfilled.",
    views: [
      ["Fulfilled in stages", "Many note the shift from \"he\" (Nebuchadnezzar, 26:7-11) to \"they\" (many nations, 26:12), and see fulfillment in stages: Nebuchadnezzar's 13-year siege of the mainland city, then Alexander the Great in 332 BC throwing the old city's rubble into the sea to build a causeway to the island.", ["cooper", "taylor"]],
      ["A partial fulfillment Ezekiel acknowledged", "Others point out that Ezekiel himself later says Nebuchadnezzar got no reward from Tyre (29:18), and read the prophecy as poetic judgment language whose full force came over time.", ["block", "duguidE"]],
    ],
    common: "All agree Tyre's proud commercial power was broken as God said, and that Ezekiel openly recorded how events unfolded.",
    bg: [["Tyre, queen of the sea", "Tyre was the leading Phoenician trading city, built partly on an island just off the coast. Its merchants sailed the whole Mediterranean, sold famous purple dye and founded colonies such as Carthage. Its wealth made it proud and secure in its own eyes.", "good", ["block", "taylor"]]],
    refs: [["EZK.29", "Ezekiel 29:17-20", "Nebuchadnezzar's labor at Tyre"], ["ISA.23", "Isaiah 23", "Oracle against Tyre"], ["REV.18", "Revelation 18", "A fallen trading city"]],
  },
  27: {
    intro: "A lament for Tyre pictured as a magnificent merchant ship built from the finest materials, trading with nations from Spain to Arabia. A long list of trading partners and goods follows. Then the east wind wrecks the ship in the heart of the seas, and sailors and merchants wail.",
    v: [
      ["27:3", "I am perfect in beauty", "Tyre boasted, \"I am perfect in beauty.\" Ezekiel pictures the city as a splendid trading ship loaded with the wealth of the world, proud of its riches."],
      ["27:5-7", "Fir trees from Senir... cedars from Lebanon... fine linen from Egypt", "Tyre's ship is built from the best of every land."],
      ["27:12", "Tarshish was your customer", "Probably in far-off Spain, the western edge of the known world."],
      ["27:26", "The east wind has broken you", "The grand ship is wrecked in the heart of the sea by the east wind. Tyre's ruin would come suddenly, and all who traded with it would mourn (27:29-32)."],
    ],
    bg: [["Tyre, queen of the sea", "Tyre was an island city off the coast of Lebanon, and its Phoenician sailors traded across the whole Mediterranean. Ezekiel 27 is one of the richest ancient lists of trade goods: silver, tin and lead, horses, ivory, ebony, spices, wool and wine.", "strong", ["block", "kitchen"]]],
    refs: [["REV.18", "Revelation 18:11-19", "Merchants weep over Babylon"], ["JAS.4", "James 4:13-16", "Boasting in plans"]],
  },
  28: {
    intro: "The prince of Tyre says, \"I am a god,\" yet he is only a man. Then a lament for the king of Tyre: \"You were the signet of perfection, full of wisdom and perfect in beauty. You were in Eden, the garden of God... You were the anointed cherub who covers.\" He was blameless until unrighteousness was found in him; his heart was lifted up because of his beauty. Sidon is judged too, and Israel will be gathered and live securely.",
    v: [
      ["28:2", "I am a god", "The ruler of Tyre said, \"I am a god.\" It is the ultimate pride: forgetting that he was only a man (28:9)."],
      ["28:13", "You were in Eden, the garden of God", "The king of Tyre is described as if he were in Eden, covered in precious stones. Readers differ: some see Satan's fall behind these words, while others read it as poetry picturing the king like a proud Adam."],
      ["28:17", "Your heart was lifted up because of your beauty", "\"Your heart was lifted up because of your beauty.\" God's gifts became the root of pride."],
      ["28:26", "They will live in it securely", "After judging the nations, God promises His people will live in their land securely, build houses and plant vineyards. There is hope for His people."],
    ],
    why: "Ezekiel 28:11-19 describes the king of Tyre as a cherub in Eden who fell through pride. Readers discuss whether it also describes Satan.",
    views: [
      ["The king of Tyre in vivid imagery", "Many scholars read it as a lament over the human king, using Eden and cherub imagery to describe his privileged position and his fall through pride.", ["block", "duguidE"]],
      ["Also a picture of Satan's fall", "Many church fathers and later teachers saw behind the king the fall of Satan, since the language goes beyond any human, comparing Isaiah 14 and Luke 10:18.", ["cooper", "taylor"]],
    ],
    common: "All agree the passage shows how pride corrupts even great gifts and leads to a fall.",
    bg: [["Wiser than Daniel", "God mocks the king of Tyre: \"You are wiser than Daniel\" (28:3). Ezekiel also names Daniel with Noah and Job as righteous men (14:14). Readers differ: some take him to be Ezekiel's contemporary in Babylon, others an ancient wise man named Danel known from Canaanite poems.", "good", ["block", "duguidE"]]],
    refs: [["ISA.14", "Isaiah 14:12-15", "The fall of the morning star"], ["GEN.3", "Genesis 3", "The garden of Eden"], ["1TI.3", "1 Timothy 3:6", "Conceit and the devil's condemnation"]],
  },
  29: {
    intro: "Pharaoh, the great monster lying in the Nile, says, \"My Nile is mine, and I myself have made it.\" God will put hooks in his jaws. Egypt has been a staff of reed to Israel that splinters when leaned on. Egypt will be humbled and never again rule over nations. Later (571 BC), God gives Egypt to Nebuchadnezzar as wages for his labor against Tyre.",
    v: [
      ["29:3", "My Nile is mine, and I myself have made it", "Pharaoh is pictured as a great river monster who says, \"My Nile is mine, and I myself have made it.\" Pride claims credit for what God made."],
      ["29:6", "A staff made of reed", "Egypt was like a reed staff that splinters and pierces the hand of anyone who leans on it (2 Kings 18:21). Judah kept trusting Egypt, and Egypt kept failing them."],
      ["29:18", "He and his army had no wages from Tyre", "Nebuchadnezzar's thirteen-year siege of Tyre left his army worn out with little plunder to show for it. Ezekiel honestly records this, and God gives Egypt to Babylon as wages instead (29:19-20)."],
    ],
    bg: [["The last date in the book", "Ezekiel 29:17 is dated to the twenty-seventh year of exile, 571 BC, the latest date in the book. It came after Nebuchadnezzar's long siege of Tyre ended. Ezekiel carefully dates his messages, which helps readers place them in history.", "strong", ["block", "kitchen"]]],
    refs: [["ISA.36", "Isaiah 36:6", "A crushed reed"], ["JER.46", "Jeremiah 46", "Egypt's defeat"]],
  },
  30: {
    intro: "\"Wail, Alas for the day! For the day is near, the day of the LORD.\" Egypt and her allies will fall to Nebuchadnezzar. God has broken Pharaoh's arm, and will strengthen the arms of the king of Babylon.",
    v: [
      ["30:3", "The day of the LORD is near", "\"The day of the LORD is near... a time of doom for the nations.\" The phrase means a day when God steps in to judge, here against Egypt."],
      ["30:13-16", "Memphis, Zoan, Thebes, Pelusium", "Ezekiel names Egypt's great cities one by one, from the delta to the far south. None is beyond God's reach."],
      ["30:20", "In the eleventh year, in the first month", "Spring of 587 BC, while Babylon besieged Jerusalem."],
      ["30:21", "I have broken the arm of Pharaoh", "\"I have broken the arm of Pharaoh.\" Egypt's attempt to rescue Jerusalem in 588 BC had already failed (Jeremiah 37:5-7), and its power would not recover."],
    ],
    bg: [["Pharaoh's broken arm", "Pharaoh Hophra (Apries) marched out to help Jerusalem in 588 BC, and the Babylonians lifted the siege for a while to face him (Jeremiah 37:5-11). He was driven back, and the siege resumed. That defeat is the \"broken arm\" of verse 21. Hophra was later overthrown by his own general.", "strong", ["block", "kitchen"]]],
    refs: [["JER.37", "Jeremiah 37:5-11", "Egypt's army turns back"], ["JER.46", "Jeremiah 46:13-26", "Nebuchadnezzar against Egypt"]],
  },
  31: {
    intro: "Pharaoh is compared to Assyria, once a towering cedar in Lebanon, the envy of every tree in Eden, with birds in its branches and nations in its shade. Because its heart was proud, it was cut down and went down to Sheol. So it will be with Pharaoh.",
    v: [
      ["31:3", "Assyria was a cedar in Lebanon", "Assyria is pictured as a towering cedar of Lebanon, giving shade to all the nations. It is a picture of a great empire at its height."],
      ["31:8", "The cedars in God's garden could not match it", "Even the trees of Eden envied it, so great was its glory."],
      ["31:10", "Its heart is haughty in its loftiness", "Because the tree grew proud of its height, God cut it down. Assyria fell to Babylon in 612-609 BC, and Egypt should learn from it."],
      ["31:16", "I made the nations quake at the sound of its fall", "The nations shook at the sound of the great tree's fall. When the mighty fall, everyone notices."],
    ],
    bg: [["Assyria's fall", "Assyria had ruled the Near East for centuries. Its capital Nineveh fell to the Babylonians and Medes in 612 BC, only about twenty-five years before this word. Pharaoh is told to look at that fallen cedar and learn.", "strong", ["block", "kitchen"]]],
    refs: [["DAN.4", "Daniel 4:10-17", "Nebuchadnezzar's tree dream"], ["NAM.3", "Nahum 3", "Assyria's fall"]],
  },
  32: {
    intro: "A lament for Pharaoh, a sea monster caught in God's net. Then a solemn picture of the grave: Egypt goes down to the pit to join Assyria, Elam, Meshech, Tubal, Edom and Sidon, mighty nations that once spread terror and now lie with the slain.",
    v: [
      ["32:1", "In the twelfth year, in the twelfth month", "Early 585 BC, about a year after Jerusalem fell."],
      ["32:2", "You are like the monster in the seas", "Pharaoh thought himself a young lion among the nations, but he was more like a monster thrashing in the rivers and muddying the water. God will catch him in His net (32:3)."],
      ["32:7", "I will cover the heavens and darken their stars", "Prophets used the darkening of sun and stars to picture the fall of a great kingdom."],
      ["32:18", "Wail for the hordes of Egypt", "Ezekiel is told to wail for Egypt and send it down to the grave with the other fallen nations. Even the mightiest empire falls."],
    ],
    bg: [["Among the uncircumcised", "Egyptians practiced circumcision, so being laid in the grave \"among the uncircumcised\" and \"those slain by the sword\" was a picture of the deepest shame for proud Pharaoh. Each nation in the list had once spread terror; now all share the same end.", "good", ["block", "duguidE"]]],
    refs: [["ISA.14", "Isaiah 14:9-11", "The grave stirs to meet them"]],
  },
  33: {
    intro: "God renews Ezekiel's call as watchman. \"As I live, I take no pleasure in the death of the wicked, but rather that the wicked turn from his way and live. Turn back, turn back from your evil ways! Why then will you die, O house of Israel?\" Then a fugitive arrives: \"The city has been taken.\" Ezekiel can speak freely again. The people enjoy hearing him like a love song, but do not obey.",
    v: [
      ["33:7", "I have appointed you a watchman", "God renews Ezekiel's call as a watchman (3:17). As the news of Jerusalem's fall draws near, his job of warning becomes more urgent."],
      ["33:11", "Turn back, turn back... Why then will you die?", "\"As I live, I take no pleasure in the death of the wicked... Turn back, turn back from your evil ways! Why then will you die?\" It shows God's heart for the lost."],
      ["33:21", "The city has been taken", "In the twelfth year of exile, a survivor arrived and said, \"The city has been taken.\" The news reached the exiles about six months after Jerusalem fell."],
      ["33:32", "Like a sensual song... they hear your words but do not practice them", "To the people Ezekiel was like a singer with a lovely voice: they enjoyed listening but did not do what he said. Listening without doing is not enough (James 1:22)."],
    ],
    w: [["צֹפֶה", "tsopheh", "H6822", "watchman, lookout", "A watchman stood on the city wall and blew the trumpet when he saw danger (33:2-6). If he warned and people ignored it, their blood was on their own heads. Ezekiel's calling as God's watchman was to warn faithfully, whatever the response.", ["halot", "block"]]],
    refs: [["EZK.18", "Ezekiel 18:23, 32", "No pleasure in death"], ["JAS.1", "James 1:22", "Be doers of the word"], ["2PE.3", "2 Peter 3:9", "Not wishing any to perish"]],
  },
  34: {
    intro: "\"Woe, shepherds of Israel who have been feeding themselves!\" They ate the fat and clothed themselves with the wool but did not care for the flock. So God says, \"I Myself will search for My sheep and seek them out... I will seek the lost, bring back the scattered, bind up the broken and strengthen the sick.\" \"I will set over them one shepherd, My servant David.\" A covenant of peace and showers of blessing.",
    v: [
      ["34:2", "Shepherds who have been feeding themselves", "Israel's leaders were shepherds who fed themselves instead of the flock. They took the wool and the meat but did not care for the weak or the lost (34:3-4)."],
      ["34:11", "I Myself will search for My sheep", "\"I Myself will search for My sheep and seek them out.\" God Himself will be their Shepherd. Jesus calls Himself the good shepherd (John 10:11) and came to seek the lost (Luke 19:10)."],
      ["34:16", "I will seek the lost", "Jesus said He came to seek and save the lost."],
      ["34:23", "One shepherd, My servant David", "God will set over them one shepherd, \"My servant David.\" David had long been dead, so this points to a future King from his line. Christians see it fulfilled in Jesus."],
      ["34:26", "There will be showers of blessing", "\"There will be showers of blessing.\" The 1883 hymn \"There Shall Be Showers of Blessing\" takes its title from this verse."],
    ],
    bg: [["Kings as shepherds", "In the ancient Near East kings often called themselves shepherds of their people. Hammurabi of Babylon used the title in his law code. So Ezekiel's attack on bad shepherds is aimed at Israel's kings and leaders, and God's promise to shepherd His people Himself is a promise of a new King.", "strong", ["block", "kitchen"]]],
    refs: [["JHN.10", "John 10:11-16", "I am the good shepherd"], ["LUK.19", "Luke 19:10", "To seek and save the lost"], ["PSA.23", "Psalm 23", "The LORD is my shepherd"]],
  },
  35: {
    intro: "An oracle against Mount Seir (Edom), which held an everlasting hatred against Israel, handed them over to the sword in their calamity, and said, \"These two nations will be mine.\" Edom will become a desolation.",
    v: [
      ["35:5", "Because you have had everlasting enmity", "Edom held \"everlasting enmity\" against Israel and turned them over to the sword in their disaster. Long-held hatred is judged."],
      ["35:6", "Since you have not hated bloodshed", "Edom stood by and helped while Judah was being slaughtered."],
      ["35:10", "Although the LORD was there", "Edom planned to take over both Israel and Judah, \"although the LORD was there.\" They forgot that God was still with His people."],
      ["35:12", "I have heard all your revilings", "God hears the taunts spoken against His people."],
    ],
    bg: [["Edom moves in", "After Jerusalem fell in 586 BC, Edomites moved into the south of Judah. In later centuries that area was called Idumea, and King Herod's family came from there. Psalm 137:7 remembers Edom shouting, \"Tear it down!\" on the day Jerusalem fell.", "good", ["block", "taylor"]]],
    refs: [["PSA.137", "Psalm 137:7", "Remember, O LORD, against the sons of Edom"], ["OBA.1", "Obadiah", "Edom's judgment"], ["GEN.27", "Genesis 27:41", "Esau's grudge"]],
  },
  36: {
    intro: "God speaks to the mountains of Israel: they will bear fruit again and be inhabited. Israel profaned God's name among the nations, \"but I had concern for My holy name.\" \"I will sprinkle clean water on you, and you will be clean... Moreover, I will give you a new heart and put a new spirit within you; and I will remove the heart of stone from your flesh and give you a heart of flesh. I will put My Spirit within you and cause you to walk in My statutes.\"",
    v: [
      ["36:22", "Not for your sake... but for My holy name", "\"It is not for your sake... but for My holy name.\" God restores Israel because of who He is, not because they deserve it. His grace is rooted in His character."],
      ["36:25", "I will sprinkle clean water on you", "\"I will sprinkle clean water on you, and you will be clean from all your filthiness.\" God Himself cleanses His people (Psalm 51:7)."],
      ["36:26", "A new heart and a new spirit", "God promises to take out the heart of stone and give a heart of flesh. Many see Jesus drawing on this passage when He speaks of being born of water and the Spirit (John 3:5)."],
      ["36:27", "I will put My Spirit within you", "\"I will put My Spirit within you and cause you to walk in My statutes.\" God's Spirit within makes obedience possible."],
    ],
    bg: [["Two prophets, one promise", "Ezekiel in Babylon and Jeremiah in Jerusalem lived at the same time and promised the same kind of inner change. Jeremiah speaks of the law written on the heart (Jeremiah 31:33); Ezekiel of a new heart and God's Spirit within (36:26-27). The New Testament sees both fulfilled in the new covenant (Hebrews 8:8-12).", "good", ["block", "duguidE"]]],
    refs: [["JHN.3", "John 3:5", "Born of water and the Spirit"], ["JER.31", "Jeremiah 31:33", "The new covenant"], ["2CO.3", "2 Corinthians 3:3", "Tablets of human hearts"]],
  },
  37: {
    intro: "The Spirit sets Ezekiel in a valley full of very dry bones. \"Son of man, can these bones live?\" \"O Lord GOD, You know.\" He prophesies, and there is a rattling; bones come together, sinews and flesh and skin cover them, but no breath. He prophesies to the breath, and they stand up, an exceedingly great army. These bones are Israel, who say, \"Our hope has perished.\" God will open their graves and put His Spirit in them. Then two sticks, Judah and Joseph, become one in his hand: one nation under one King, David, with an everlasting covenant of peace.",
    v: [
      ["37:3", "Can these bones live?", "God sets Ezekiel in a valley of dry bones and asks, \"Can these bones live?\" It is a picture of a situation beyond all human hope."],
      ["37:4", "O dry bones, hear the word of the LORD", "Ezekiel is told to preach to the bones: \"O dry bones, hear the word of the LORD.\" God's word brings life where there is none."],
      ["37:9", "Come from the four winds, O breath", "The Hebrew word ruach means breath, wind and Spirit. The breath that fills these bodies is the same Spirit God promised in 36:27 (compare Genesis 2:7; John 20:22)."],
      ["37:11", "Our hope has perished", "The bones are Israel in exile, saying, \"Our bones are dried up and our hope has perished.\" God's answer to despair is to open their graves (37:12)."],
      ["37:24", "My servant David will be king over them", "The two sticks joined in Ezekiel's hand (37:15-22) show Judah and Israel made one nation again under one King, \"My servant David.\""],
    ],
    w: [["רוּחַ", "ruach", "H7307", "breath, wind, spirit", "One Hebrew word means breath, wind and Spirit. Ezekiel 37 uses all three meanings: the wind blows, the breath enters, and God's Spirit gives life.", ["halot", "block"]]],
    refs: [["GEN.2", "Genesis 2:7", "God breathed into man the breath of life"], ["JHN.20", "John 20:22", "Jesus breathed on them: Receive the Holy Spirit"], ["ROM.8", "Romans 8:11", "He will give life to your mortal bodies"]],
  },
  38: {
    intro: "Gog, of the land of Magog, chief prince of Meshech and Tubal, will gather a vast coalition and attack Israel \"in the latter years,\" when the people are living securely in unwalled villages. But God will rise up against Gog with earthquake, plague, hail and fire. \"I will magnify Myself... and they will know that I am the LORD.\"",
    v: [
      ["38:8", "In the latter years", "Gog of the land of Magog will come against Israel \"in the latter years.\" Readers differ on whether this describes one future war, a past event, or a symbolic picture of the last enemy (compare Revelation 20:8)."],
      ["38:11", "Unwalled villages... living securely", "The invader plans to attack people living in unwalled villages, at peace and without defenses. God's restored people are pictured at rest."],
      ["38:23", "I will make Myself known in the sight of many nations", "\"I will make Myself known in the sight of many nations.\" However it is read, the purpose of the battle is the same: that all will know the LORD."],
    ],
    why: "Scholars and teachers read the Gog and Magog prophecy (38-39) in different ways.",
    views: [
      ["A future literal battle", "Some read it as a specific future invasion of Israel by a northern coalition before or during the end times, often linked to Revelation's timeline.", ["cooper"]],
      ["A symbolic picture of God's final victory", "Others read Gog as a symbol of all the forces that oppose God's people, gathered in one great final attack and defeated, as Revelation 20:8 uses \"Gog and Magog\" for the nations of the whole earth.", ["block", "taylor", "duguidE"]],
    ],
    common: "All agree that God will protect His people and finally defeat every enemy, so that all nations will know He is the LORD.",
    bg: [["Gog and Magog", "Magog is named as a son of Japheth in Genesis 10:2, a people of the far north. Some scholars connect Gog with Gyges, a seventh-century king of Lydia. Translations also differ over \"Rosh\": a title, \"chief prince,\" or the name of a place. Readers differ on how the whole prophecy will be fulfilled.", "good", ["block", "taylor", "cooper"]]],
    refs: [["REV.20", "Revelation 20:7-10", "Gog and Magog"], ["ZEC.14", "Zechariah 14", "Nations gathered against Jerusalem"]],
  },
  39: {
    intro: "Gog falls on the mountains of Israel. The people burn the weapons for seven years and bury the dead for seven months. Birds and beasts are invited to a great feast. Then God promises: \"Now I will restore the fortunes of Jacob... I will not hide My face from them any longer, for I will have poured out My Spirit on the house of Israel.\"",
    v: [
      ["39:9", "They will make fires with the weapons", "The people will burn the enemy's weapons for fuel for seven years. Weapons will no longer be needed."],
      ["39:25", "I will restore the fortunes of Jacob", "\"Now I will restore the fortunes of Jacob and have mercy on the whole house of Israel.\" After judgment comes mercy."],
      ["39:29", "I will not hide My face from them any longer", "\"I will not hide My face from them any longer, for I will have poured out My Spirit.\" God's face is turned toward His people again."],
    ],
    bg: [["Seven months of burial", "After Gog's defeat, it takes Israel seven months to bury the dead and cleanse the land, in a valley renamed Hamon-gog, \"the multitude of Gog\" (39:11-12). The details stress how complete God's victory is.", "good", ["block", "cooper"]]],
    refs: [["REV.19", "Revelation 19:17-18", "The great supper of God"], ["JOL.2", "Joel 2:28", "I will pour out My Spirit"]],
  },
  40: {
    intro: "In 573 BC, twenty-five years into exile, Ezekiel is taken in a vision to a very high mountain in Israel. A man shining like bronze, with a measuring line and rod, shows him a temple and measures everything: walls, gates, courts, rooms and altars. \"Declare to the house of Israel all that you see.\" Chapters 40-48 describe this temple and land in great detail.",
    v: [
      ["40:2", "On a very high mountain", "In the twenty-fifth year of exile, about 573 BC, God set Ezekiel on a very high mountain in a vision. High mountains in Scripture are often places of God's presence (Isaiah 2:2)."],
      ["40:3", "A man whose appearance was like bronze", "A man who looked like bronze, holding a measuring rod and a line, became Ezekiel's guide. Revelation 11:1 and 21:15 also use measuring to show God's care for His holy place."],
      ["40:4", "Declare to the house of Israel all that you see", "Ezekiel is told to declare everything he sees. For exiles with no temple, the vision was a promise that God would dwell with them again. Christians differ on whether it describes a future building, the church, or the new creation."],
    ],
    why: "Ezekiel 40-48 describes a temple, sacrifices and land divisions that were never built as described. Scholars and teachers read these chapters in different ways.",
    views: [
      ["A future temple", "Some expect a literal temple to be built in a future age, with these chapters as its blueprint.", ["cooper"]],
      ["A picture of God dwelling with His people", "Many read the vision as symbolic, using the familiar language of temple and land to show perfect worship and God's presence fulfilled in Christ and the church and finally in the new creation, which Revelation 21-22 describes with Ezekiel's images.", ["block", "taylor", "duguidE"]],
    ],
    common: "All agree the vision promises that God's glory will return and dwell with a cleansed, restored people, and that life will flow from His presence.",
    bg: [["The long cubit", "The guide's rod measured six long cubits, each a cubit plus a handbreadth (40:5), about 20.5 inches instead of the common 17.5. The same royal cubit was used in Egypt. Ezekiel's temple vision is full of exact numbers that stress order and holiness.", "good", ["block", "kitchen"]]],
    refs: [["REV.21", "Revelation 21:10-22", "The holy city measured"], ["ZEC.2", "Zechariah 2:1-5", "A man with a measuring line"], ["JHN.2", "John 2:19-21", "The temple of His body"]],
  },
  41: {
    intro: "The guide measures the temple building itself: the nave, the inner room (the Most Holy Place), side rooms on three levels, and walls carved with cherubim and palm trees, each cherub with two faces, a man's and a lion's. A wooden altar stands before the LORD.",
    v: [
      ["41:4", "This is the most holy place", "The guide measured the innermost room, twenty cubits square, and said, \"This is the most holy place.\" Only the guide entered it; Ezekiel the priest stayed outside."],
      ["41:18", "Cherubim and palm trees", "The walls were carved with cherubim and palm trees, each cherub with the face of a man and of a lion. They recall Eden and the presence of God."],
      ["41:22", "This is the table that is before the LORD", "A wooden altar is called \"the table that is before the LORD.\" Worship is pictured as a meal in God's presence."],
    ],
    bg: [["No ark in sight", "Ezekiel's temple has a most holy place but no mention of the ark of the covenant, the lampstand or the veil. Jeremiah had said the ark would no longer be remembered (Jeremiah 3:16). Readers differ on what this means for how the vision should be read.", "good", ["block", "taylor"]]],
    refs: [["1KI.6", "1 Kings 6", "Solomon's temple"], ["HEB.9", "Hebrews 9:1-12", "The true holy place"]],
  },
  42: {
    intro: "The guide shows Ezekiel the priests' chambers, where they eat the most holy offerings and change their garments. Then he measures the outer wall, 500 rods on each side, \"to divide between the holy and the profane.\"",
    v: [
      ["42:13", "The holy chambers where the priests... shall eat the most holy things", "Rooms set apart so holy food and holy work stayed separate from ordinary life."],
      ["42:14", "They shall lay their garments in which they minister", "Priests were to leave their holy garments in special rooms before going out among the people. Holiness in worship was carefully guarded."],
      ["42:20", "To divide between the holy and the profane", "A wall around the whole area divided the holy from the common. God's holiness is protected."],
    ],
    bg: [["Reeds or cubits?", "The Hebrew text of 42:16-20 says each side measured 500 reeds (about a mile), while the Greek translation reads 500 cubits (about 850 feet), which fits the measurements of chapter 40. Translations differ here, but either way the wall marks a clear line around what is holy.", "debated", ["block", "taylor"]]],
    refs: [["LEV.10", "Leviticus 10:10", "Distinguish between holy and common"]],
  },
  43: {
    intro: "The glory of the God of Israel comes from the east, with a sound like many waters, and the earth shines with His glory. It enters the temple by the east gate and fills the house. God says, \"This is the place of My throne... where I will dwell among the sons of Israel forever.\" The altar is described and consecrated.",
    v: [
      ["43:2", "His voice was like the sound of many waters", "The same description as the risen Jesus (Revelation 1:15)."],
      ["43:5", "The glory of the LORD filled the house", "The glory that left in chapter 10 returns."],
      ["43:7", "I will dwell among the sons of Israel forever", "The glory that left in chapter 10 returns from the east and fills the house. God says, \"This is the place of My throne... where I will dwell among the sons of Israel forever.\""],
    ],
    w: [["כָּבוֹד", "kavod", "H3519", "glory, weight, honor", "The root means heavy. God's glory is the weight of His presence. Ezekiel saw it leave the temple (10:18) and now sees it return: \"the glory of the LORD filled the house\" (43:5). He fell on his face, as he had at the beginning (1:28).", ["halot", "block"]]],
    refs: [["EZK.10", "Ezekiel 10:18-19", "The glory departs"], ["REV.1", "Revelation 1:15", "His voice like the sound of many waters"], ["JHN.1", "John 1:14", "We beheld His glory"]],
  },
  44: {
    intro: "The east gate is shut because the LORD entered by it; only the prince may sit there to eat before the LORD. Foreigners uncircumcised in heart may not enter. The Levites who served idols lose their priestly rank; the faithful sons of Zadok will minister and teach the people the difference between holy and common.",
    v: [
      ["44:2", "This gate shall be shut", "The east gate was to stay shut because the LORD had entered by it. The present Golden Gate on Jerusalem's east wall has been sealed for centuries, and some people connect it with this verse."],
      ["44:15", "The sons of Zadok, who kept charge of My sanctuary", "The priests descended from Zadok stayed faithful when others strayed, so they alone would serve at God's altar. Faithfulness is rewarded."],
      ["44:23", "Teach My people the difference between the holy and the profane", "Priests were to teach the people the difference between the holy and the common, the clean and the unclean. Teaching was part of a priest's calling (Malachi 2:7)."],
    ],
    bg: [["Levites who strayed", "Levites who had led Israel into idolatry would still serve in the temple, guarding gates and helping, but could not come near the holy things (44:10-14). Faithful service brought nearness; unfaithfulness had lasting results, though not complete rejection.", "good", ["block", "duguidE"]]],
    refs: [["1SA.2", "1 Samuel 2:35", "A faithful priest"], ["MAL.2", "Malachi 2:7", "The lips of a priest preserve knowledge"]],
  },
  45: {
    intro: "A holy portion of land is set apart for the sanctuary, priests and Levites, with land for the prince on each side. God commands the princes: \"Put away violence and destruction, and practice justice and righteousness.\" Honest weights and measures, and offerings for the feasts.",
    v: [
      ["45:1", "An allotment to the LORD, a holy portion", "A holy portion of land is set apart for the LORD at the center of the land. God is at the center of His people's life."],
      ["45:9", "Practice justice and righteousness", "\"Enough, you princes of Israel; put away violence and destruction, and practice justice and righteousness.\" Leaders must not oppress the people."],
      ["45:10", "You shall have just balances", "\"You shall have just balances.\" Honest weights and measures were part of honoring God (Proverbs 11:1)."],
    ],
    bg: [["Sacrifices in a future temple", "The vision includes sin offerings and other sacrifices (45:17-25). Readers differ on how to understand this: as memorials of Christ's finished work, as the vision's way of picturing perfect worship in the terms Ezekiel knew, or in other ways. Hebrews 10:10-14 teaches that Christ's sacrifice was offered once for all.", "good", ["block", "taylor", "cooper"]]],
    refs: [["MIC.6", "Micah 6:8, 11", "Do justice; dishonest scales"], ["PRO.11", "Proverbs 11:1", "A false balance"]],
  },
  46: {
    intro: "Rules for worship on Sabbaths and new moons. The people enter by one gate and leave by the opposite gate, so no one turns back. The prince worships among the people. Kitchens are set in the corners of the court for cooking the offerings.",
    v: [
      ["46:9", "He shall go straight out", "Worshipers who came in by the north gate were to leave by the south gate, and the reverse. No one went back the way they came; worship moves forward."],
      ["46:10", "The prince shall go in among them", "The prince was to go in and out with the people, not apart from them. The leader worships alongside everyone else."],
      ["46:16-18", "The prince shall not take from the people's inheritance", "Leaders may not seize family land, the very sin of Ahab against Naboth (1 Kings 21)."],
    ],
    bg: [["Reading Ezekiel's temple", "Chapters 40-48 describe a temple and its worship in great detail. Careful readers understand it in different ways: as a future temple, as a picture of God dwelling with a restored people, or as fulfilled in Christ and the new creation. The note on Ezekiel 40 sets out these views fairly.", "good", ["block", "duguidE"]]],
    refs: [["1KI.21", "1 Kings 21", "Naboth's vineyard"], ["PSA.42", "Psalm 42:4", "Going with the throng to the house of God"]],
  },
  47: {
    intro: "Water flows from under the threshold of the temple toward the east. Ezekiel's guide measures it: ankle-deep, knee-deep, waist-deep, then a river too deep to cross. Where it flows into the Dead Sea, the water becomes fresh and teems with fish, and fishermen spread nets. Trees on both banks bear fruit every month, \"and their leaves for healing.\" The land's borders are drawn, and foreigners living among Israel receive an inheritance too.",
    v: [
      ["47:1", "Water was flowing from under the threshold", "Water flowed from under the threshold of the temple toward the east. Life flows out from God's presence (Joel 3:18; Zechariah 14:8)."],
      ["47:5", "A river that I could not ford", "Ankle-deep, then knee-deep, then waist-deep, and finally a river too deep to cross. God's blessing keeps getting deeper."],
      ["47:9", "Everything will live where the river goes", "Wherever the river flows, everything lives. Even the salty Dead Sea becomes fresh, with fishermen spreading nets from En-gedi (47:10)."],
      ["47:12", "Their leaves for healing", "Fruit trees grow along the river, bearing every month, \"and their leaves for healing.\" Revelation 22:2 echoes this picture."],
      ["47:22", "The aliens who stay in your midst... shall have an inheritance", "Foreigners who live among Israel and raise families there will receive an inheritance like the native-born. There is room in God's land for outsiders."],
    ],
    bg: [["Healing the Dead Sea", "The Dead Sea is about 34 percent salt, roughly ten times saltier than the ocean, and no fish live in it. In Ezekiel's vision, the river from the temple makes its waters fresh, and fishermen spread nets from En-gedi to En-eglaim (47:8-10). Only the marshes stay salty, for salt (47:11).", "good", ["block", "cooper"]]],
    refs: [["REV.22", "Revelation 22:1-2", "The river of the water of life"], ["JHN.7", "John 7:37-39", "Rivers of living water"], ["ZEC.14", "Zechariah 14:8", "Living waters from Jerusalem"]],
  },
  48: {
    intro: "The land is divided among the twelve tribes in parallel strips, with the holy portion in the middle. The city has twelve gates named for the tribes, three on each side. The book ends with the city's new name: \"The LORD is there.\"",
    v: [
      ["48:8-10", "The holy allotment", "God's sanctuary stands at the center, with the tribes around it."],
      ["48:31", "The gates of the city shall be named after the tribes", "The city has twelve gates named after the twelve tribes, so every tribe has a place. Revelation 21:12 describes the new Jerusalem the same way, and the book ends with the city's name: \"The LORD is there\" (48:35)."],
      ["48:35", "The LORD is there", "Hebrew: Yahweh Shammah. The best thing about the city is God's presence."],
    ],
    bg: [["Every tribe has a place", "Unlike Joshua's division of the land, Ezekiel's tribes receive equal strips running east to west, with the sanctuary in the middle. Even the tribes of servant-wives' sons get full shares. Revelation 21 takes up the twelve gates with the tribes' names.", "good", ["block", "duguidE"]]],
    refs: [["REV.21", "Revelation 21:3, 12-13", "Twelve gates; God dwells with them"], ["MAT.1", "Matthew 1:23", "Immanuel, God with us"]],
  },
});
